  ["GVG Faction Transform"] = "Transformação de Facção GVG",
  ["GVG High Tower Effect Buff Underworld Emperor"] = "GVG Efeito Torre Alta Buff Imperador do Submundo",
  ["GVG High Tower Effect Buff Night Emperor"] = "GVG Efeito Torre Alta Buff Night Emperor",
  ["GVG High Tower Effect Buff Blood Emperor"] = "GVG Efeito Torre Alta Buff Blood Emperor",
  ["GVG High Tower Effect Buff Black Emperor"] = "GVG Efeito Torre Alta Buff Imperador Negro",
  ["Game.QuestSystem.GetTaskExcelCfg failed to retrieve RingID = %s, returned nil"] = "Game.QuestSystem.GetTaskExcelCfg falhou ao recuperar RingID = %s , retornou nulo",
  ["Good day, {{Sir|Madam}}, welcome to the Club."] = "Bom dia, {{Senhor|Senhora}}, bem vindo ao Clube.",
  ["Good day, {{Sir|Madam}}, would you like some tea and snacks?"] = "Bom dia, {{Senhor|Senhora}}, gostaria de um pouco de chá e lanches?",
  ["Good day, {{Sir|Madam}}. I am Jacob, a city guide certified by the City Hall. I can plan the most efficient tour route for you and answer most of your questions about this city."] = "Bom dia, {{Senhor|Senhora}}. Sou Jacob, guia da cidade certificado pela Prefeitura. Posso planejar a rota turística mais eficiente para você e responder a maioria das suas perguntas sobre esta cidade.",
  ["Good day, Madam. I am Jacob, a city guide certified by the City Hall. I can plan the most efficient tour route for you and answer most of your questions about this city."] = "Bom dia, senhora. Sou Jacob, guia da cidade certificado pela Prefeitura. Posso planejar a rota turística mais eficiente para você e responder a maioria das suas perguntas sobre esta cidade.",
  ["Goodbye, warm {Sir|Madam}!"] = "Adeus, caloroso {Senhor | Senhora}!",
  ["Grab {{him|her}}, take it to the \"Professor\" for research!"] = "Agarre {{ele|ela}}, leve-o ao \"Professor\" para pesquisa!",
  ["GuildSystem: onRetSetGuildHero failed to set Club hero, errorCode="] = "GuildSystem: onRetSetGuildHero falhou ao definir o herói do clube, errorCode=",
  ["GvG Historical Battle Record Interface Introduction"] = "Introdução à Interface de Registro Histórico de Batalha GvG",
  ["Trigger 35% Max Health Shield when HP < 40%"] = "Ative 35% do Escudo de Saúde Máximo quando HP < 40%",
  ["Trigger 3s Invincibility when HP < 40%"] = "Aciona Invencibilidade por 3s quando HP < 40%",
  ["Additional 15% damage reduction when HP < 50%"] = "Redução adicional de 15% de dano quando HP <50%",
  ["Additional 20% damage reduction when HP < 50%"] = "Redução adicional de 20% de dano quando HP <50%",
  ["Trigger 50% Max Health Shield when HP < 60%"] = "Ative 50% do Escudo de Saúde Máximo quando HP <60%",
  ["Trigger 80% Max Health Shield when HP < 60%"] = "Ative 80% do Escudo de Saúde Máximo quando HP <60%",
  ["Trigger 1.5s Invincibility when HP is low"] = "Aciona 1,5s de invencibilidade quando o HP está baixo",
  ["Trigger 1s Invincibility when HP is low"] = "Aciona 1s de invencibilidade quando o HP está baixo",
  ["HUD_GroupMemberItem:Refresh could not find class status %s"] = "HUD_GroupMemberItem:A atualização não conseguiu encontrar o status da turma %s",
  ["HUD_WatchGame_Skill_Common:RefreshSkill could not find Skill configuration, skillId=%s"] = "HUD_WatchGame_Skill_Common:RefreshSkill não conseguiu encontrar a configuração da habilidade, skillId= %s",
  ["HUD Bottom-Left Save"] = "Salvar canto inferior esquerdo do HUD",
  ["HUD Always Visible Bottom-Right"] = "HUD sempre visível no canto inferior direito",
  ["HUD Always Visible Bottom-Left"] = "HUD sempre visível no canto inferior esquerdo",
  ["Hahaha, I wouldn't dare face a monster of your Angel level, but I am taking {{him|her}} with me."] = "Hahaha, eu não ousaria enfrentar um monstro do seu nível de Anjo, mas estou levando {{ele|ela}} comigo.",
  ["Hello there, {{young sir|young lady}}. The aroma of bread is always pleasant; it's truly wonderful."] = "Olá, {{jovem senhor | mocinha}}. O aroma do pão é sempre agradável; é realmente maravilhoso.",
  ["Hello {{Sir|Madam}}, are you looking for a divination, or do you want to join our Club?"] = "Olá {{Senhor|Senhora}}, você está procurando um adivinhação ou deseja se juntar ao nosso Clube?",
  ["Hello, {{sir|madam}}. Welcome to Tingen. Please allow me to recommend our agency's sightseeing carriage tour service."] = "Olá, {{senhor|senhora}}. Bem vindo a Tingen. Por favor, permita-me recomendar o serviço de passeio turístico em carruagem da nossa agência.",
  ["Hello, {{PlayerName}}{{Sir|Madam}}, happy to be of service."] = "Olá, {{PlayerName}}{{Senhor|Senhora}}, fico feliz em poder ajudar.",
  ["Hello, {{Sir|Madam}}! Would you like to buy a ticket?"] = "Olá, {{Senhor|Senhora}}! Gostaria de comprar um ingresso?",
  ["Hello, {{Sir|Madam}}, I see the light of thirst for knowledge shining on your face!"] = "Olá, {{Senhor|Senhora}}, vejo a luz da sede de conhecimento brilhando em seu rosto!",
  ["Hello, {{Sir|Madam}}, it's a pleasure to see you. What would you like to eat?"] = "Olá, {{Senhor|Senhora}}, é um prazer vê-lo. O que você gostaria de comer?",
  ["Hello, {{Sir|Madam}}, the Very Fun Hotel welcomes you!"] = "Olá, {{Senhor|Senhora}}, o Very Fun Hotel lhe dá as boas-vindas!",
  ["Hello, {{Sir|Madam}}, we meet again."] = "Olá, {{Senhor|Senhora}}, nos encontramos novamente.",
  ["Hello, {{Sir|Madam}}, welcome to the Club."] = "Olá, {{Senhor|Senhora}}, bem vindo ao Clube.",
  ["Hello, {{Sir|Madam}}."] = "Olá, {{Senhor|Senhora}}.",
  ["Hello, {{sir|madam}}. As you can see, I am researching a... magical bill regarding sewage treatment."] = "Olá, {{senhor|senhora}}. Como você pode ver, estou pesquisando um projeto de lei mágico sobre tratamento de esgoto.",
  ["Hello, {{handsome sir|elegant lady}}."] = "Olá, {{bonito senhor | senhora elegante}}.",
  ["Here!—Oh, sorry, {{sir|madam}}, I thought the person inside was notifying me for the interview."] = "Aqui!—Oh, desculpe, {{senhor | senhora}}, pensei que a pessoa lá dentro estava me notificando para a entrevista.",
  ["Hey {{sir|madam}}! Want to try a drink that bites your tongue? Only 1 penny, punchier than sweet iced tea, and more refreshing than ginger beer!"] = "Ei {{senhor|senhora}}! Quer experimentar uma bebida que morde a língua? Apenas 1 centavo, mais forte que o chá gelado doce e mais refrescante que a cerveja de gengibre!",
  ["Hey {{sir|madam}}, need a ride? If not, do you need anything delivered?"] = "Ei {{senhor|senhora}}, precisa de uma carona? Se não, você precisa que alguma coisa seja entregue?",
  ["Hey! {{sir|madam}}, I have, I have other poems!"] = "Ei! {{senhor | senhora}}, tenho, tenho outros poemas!",
  ["Hey, I don't know where this ship is headed. But I think my opportunity has arrived... Do you want a painting, {{sir|madam}}?"] = "Ei, não sei para onde esse navio está indo. Mas acho que minha oportunidade chegou... Você quer uma pintura, {{senhor|senhora}}?",
  ["Hey, {{sir|madam}}, don't say that! You must know that wisdom is also one of the ways to earn money, of course, of course! It's not necessarily moral."] = "Ei, {{senhor|senhora}}, não diga isso! Você deve saber que a sabedoria também é uma das formas de ganhar dinheiro, claro, claro! Não é necessariamente moral.",
  ["Hey, {{sir|madam}}, welcome to the best market in the West Alley!"] = "Ei, {{senhor | senhora}}, bem-vindo ao melhor mercado do West Alley!",
  ["Hey, {{young man|young lady}}! You'd better stay aside, it's dangerous near the cargo boxes."] = "Ei, {{jovem | mocinha}}! É melhor você ficar de lado, é perigoso perto das caixas de carga.",
  ["HomelandLevel = %s does not exist in LevelUp_ManorUpgrade.xlsx"] = "HomelandLevel = %s não existe em LevelUp_ManorUpgrade.xlsx",
  ["How is it, {{sir|madam}}? Have you seen what our recent fortunes are?"] = "Como está, {{senhor|senhora}}? Você viu quais são nossas fortunas recentes?",
  ["However, every drink here comes from the gift of the dragon. Enjoy the deliciousness, {{sir|madam}}."] = "No entanto, cada bebida aqui vem do presente do dragão. Aproveite a delícia, {{senhor | senhora}}.",
  ["I can guide {{him|her}}."] = "Eu posso guiar {{ele|ela}}.",
  ["I knew it, {{sir|madam}}, you look like the kind of person who cares about health, so naturally you would mind those vegetables watered with industrial wastewater."] = "Eu sabia, {{senhor | senhora}}, você parece o tipo de pessoa que se preocupa com a saúde, então naturalmente você se importaria com aqueles vegetais regados com águas residuais industriais.",
  ["I plan to let {{him|her}} go for a walk in Tingen again to learn more about this place."] = "Pretendo deixar {{ele|ela}} dar um passeio em Tingen novamente para aprender mais sobre este lugar.",
  ["I really heard him speak! That voice came from his room! Detective {{sir|madam}}, you have to believe me!"] = "Eu realmente o ouvi falar! Essa voz veio do quarto dele! Detetive {{senhor|senhora}}, você tem que acreditar em mim!",
  ["I should go. Help me pass this note to {{PlayerName}}. Entering the fog of history consumed too much spirituality. Let {{him|her}} have a good rest at Blackthorn tonight."] = "Eu deveria ir. Ajude-me a passar esta nota para {{PlayerName}}. Entrar na névoa da história consumiu muito espiritualidade . Deixe {{ele | ela}} ter um bom descanso em Blackthorn esta noite.",
  ["I think this {{sir|madam}}'s sense of style isn't bad. If you are considering joining the Tingen Fashion Association..."] = "Eu acho que o senso de estilo deste {{senhor|senhora}} não é ruim. Se você está pensando em ingressar na Tingen Fashion Association...",
  ["I understand... Jonar, please let me talk to {{him|her}}<P_Yellow> alone</>."] = "Eu entendo... Jonar, por favor, deixe-me falar com {{ele|ela}} <P_Yellow> sozinho </> .",
  ["I'm Enid {{sir|sister}}, are you so sleepy you've forgotten your own name?"] = "Meu nome é Enid {{senhor | irmã}}, você está com tanto sono que esqueceu seu próprio nome?",
  ["I'm not too sure either... {{respected sir|respected madam}}, if you're willing, please help me find the specific addresses!"] = "Também não tenho muita certeza... {{respeitado senhor|respeitada senhora}}, se você estiver disposto, por favor me ajude a encontrar os endereços específicos!",
  ["IDLE animation asset"] = "Recurso de animação IDLE",
  ["ID copied to clipboard."] = "ID copiado para a área de transferência.",
  ["IOS Frame Capture"] = "Captura de quadros IOS",
  ["Capture current frame on iOS."] = "Capture o quadro atual no iOS.",
  ["iOS Recommended Server"] = "Servidor recomendado para iOS",
  ["iOS Review Server"] = "Servidor de revisão iOS",
