  ["Id (Gatherable object)"] = "Id (objeto coletável)",
  ["Id (Trap)."] = "ID (armadilha).",
  ["Id (Extra Damage Boost)."] = "Id (aumento de dano extra).",
  ["IdGroup (Sub-entity)"] = "IdGroup (subentidade)",
  ["IdGroup (Skill)"] = "IdGroup (habilidade)",
  ["IdGroup(Item)"] = "IdGrupo(Item)",
  ["ClientTimelineID in Idle state."] = "ClientTimelineID em estado inativo.",
  ["Double jump animation in Idle state."] = "Animação de salto duplo no estado inativo.",
  ["If that is indeed the reason, {{sir|madam}}, could I ask you to help look after this old gentleman?"] = "Se esse for realmente o motivo, {{senhor | senhora}}, posso pedir-lhe para ajudar a cuidar deste velho senhor?",
  ["In <Mark> TRPG </> gameplay, after rolling a <Mark> Critical Success </>, Attack increased by <Mark> 125 </>. <Mark>{1,1,(applied)}</>"] = "No jogo <Mark> TRPG </>, depois de obter um <Mark> Sucesso Crítico </> , o Ataque aumentou em <Mark> 125 </> . <Mark> {1,1,(aplicado)} </>",
  ["In any case, {{sir|madam}}, how much are you willing to pay for this music box?"] = "De qualquer forma, {{senhor|senhora}}, quanto você está disposto a pagar por esta caixa de música?",
  ["InPath = effect blueprint path, (sx, sy, sz, sw, px, py, pz) = transform."] = "InPath = caminho do blueprint do efeito, (sx, sy, sz, sw, px, py, pz) = transformação.",
  ["InputBase:BindInput duplicate bind %s"] = "InputBase:BindInput ligação duplicada %s",
  ["InputBase:UnBindInput Error UnBind %s %s %s"] = "InputBase:UnBindInput Erro UnBind %s %s %s",
  ["Is that really okay? {{sir|madam}}, why are you helping me like this?"] = "Isso está realmente bem? {{senhor | senhora}}, por que você está me ajudando assim?",
  ["Isn't there still {{him|her}}?"] = "Ainda não existe {{ele | ela}}?",
  ["It is a pleasure to see you, {{sir|madam}}."] = "É um prazer vê-lo, {{senhor|senhora}}.",
  ["It seems this {{sir|madam}} has been listening to our discussion for a long time, are you also a loyal reader of Miss Fors?"] = "Parece que este {{senhor | senhora}} está ouvindo nossa discussão há muito tempo, você também é um leitor fiel de Miss Fors?",
  ["It's more than that, {{sir|madam}}. Bayam is famous across the sea for its spices, brothels, and casinos. Once you touch gambling, it's hard to get out."] = "É mais do que isso, {{senhor|senhora}}. Bayam é famosa do outro lado do mar por suas especiarias, bordéis e cassinos. Depois de começar a jogar, é difícil sair.",
  ["It's okay, Consultant {{sir|madam}}, leave the rest to us."] = "Está tudo bem, Consultor {{senhor|senhora}}, deixe o resto conosco.",
  ["It's you! Kind {{sir|madam}}"] = "É você! Gentil {{senhor | senhora}}",
  ["It's {{PlayerName}}{{brother|sister}}! My sister went to train, and she left a letter for you."] = "É {{PlayerName}}{{irmão|irmã}}! Minha irmã foi treinar e deixou uma carta para você.",
  ["ItrCol_Inside switch"] = "Chave ItrCol_Inside",
  ["ItrCol_Outside Switch"] = "Comutador ItrCol_Outside",
  ["Itr_Inside switch"] = "Interruptor Itr_Inside",
  ["Itr_Switch Outside"] = "Itr_Switch Fora",
  ["J2 turns into Spade 7"] = "J2 se transforma em Espada 7",
  ["Jimmy, {{sir|madam}}... Mom works as a maid during the day and has to go out to dance in very cold clothes at night. She said she would send me to be an apprentice when she saved enough money. But... but the police said Mom did something bad... is Mom a bad person?"] = "Jimmy, {{senhor|senhora}}... Mamãe trabalha como empregada doméstica durante o dia e tem que sair para dançar com roupas muito frias à noite. Ela disse que me enviaria para ser aprendiz quando economizasse dinheiro suficiente. Mas... mas a polícia disse que mamãe fez algo ruim... mamãe é uma pessoa má?",
  ["J becomes Club 4"] = "J se torna o Clube 4",
  ["KeyboardShortcutItem:OnRefresh could not find the corresponding refresh function: %s"] = "KeyboardShortcutItem:OnRefresh não conseguiu encontrar a função de atualização correspondente: %s",
  ["KeyboardShortcutUtils.GetShortcutKeyData: could not find the corresponding shortcut key configuration, shortcut: %s"] = "KeyboardShortcutUtils.GetShortcutKeyData: não foi possível encontrar a configuração da tecla de atalho correspondente, atalho: %s",
  ["KimID = mailbox prefix, optional (only displays on client)."] = "KimID = prefixo da caixa postal, opcional (exibido apenas no cliente).",
  ["Kind {{sir|madam}}, have you found the matches for Jenny?"] = "Gentil {{senhor | senhora}}, você encontrou as correspondências para Jenny?",
  ["Kind {{sir|madam}}, if you like my dance, please go to the meat stall in front and support my sister Mary Jane's business."] = "Gentil {{senhor | senhora}}, se você gosta da minha dança, por favor vá até a barraca de carne na frente e apoie os negócios da minha irmã Mary Jane.",
  ["Kind {{sir|madam}}, please give a little more... there are many other children who haven't eaten..."] = "Gentil {{senhor|senhora}}, por favor, dê um pouco mais... há muitas outras crianças que não comeram...",
  ["Kind {{sir|madam}}, thank you for listening to my rambling. Knowing that there is still someone in this world who remembers Jenny is enough to comfort me."] = "Gentil {{senhor | senhora}}, obrigado por ouvir minhas divagações. Saber que ainda existe alguém neste mundo que se lembra de Jenny é o suficiente para me confortar.",
  ["K Gold Coin"] = "Moeda de Ouro K",
  ["Start LUA memory profiling"] = "Iniciar perfil de memória LUA",
  ["End LUA memory profiling"] = "Encerrar perfil de memória LUA",
  ["Start LUA performance profiling"] = "Iniciar perfil de desempenho LUA",
  ["End LUA performance profiling"] = "Encerrar o perfil de desempenho LUA",
  ["L_IDLE = 101, -- Standing idle \n L_MOVE = 102, -- Movement, such as walk/run/sprint \n L_MOVE_TURN = 103, -- Move turn \n L_DODGE = 104, -- Dash \n L_JUMP = 105, -- Jump \n L_DROPPING = 106, -- Falling"] = "L_IDLE = 101, -- Parado ocioso \n L_MOVE = 102, -- Movimento, como caminhada/corrida/sprint \n L_MOVE_TURN = 103, -- Mover turno \n L_DODGE = 104, -- Dash \n L_JUMP = 105, -- Jump \n L_DROPPING = 106, -- Caindo",
  ["Last time after praying to the Lord of the Washroom, a policeman {{sir|madam}} descended from the sky and helped us solve the diarrhea problem. If we pray again, could it resurrect 'Caramel Bomb'?"] = "Da última vez, depois de orar ao Senhor do Banheiro, um policial {{senhor | senhora}} desceu do céu e nos ajudou a resolver o problema da diarreia. Se orarmos novamente, será que isso poderia ressuscitar a 'Bomba de Caramelo'?",
  ["Mapping relationship from Layer count to attached object Tag."] = "Mapeamento do relacionamento da contagem de camadas para o Tag do objeto anexado.",
  ["Leo camera"] = "Câmera Leão",
  ["Let me heal the soul of {{him|her}} tormented by nightmares"] = "Deixe-me curar a alma de {{ele|dela}} atormentada por pesadelos",
  ["Let {{him|her}} in."] = "Deixe {{ele | ela}} entrar.",
  ["Let's go. Take your \"darling,\" thank this {{brother|sister}} who helped me find you, and let's go home."] = "Vamos. Pegue seu \"querido\", agradeça a esse {{irmão|irmã}} que me ajudou a encontrar você, e vamos para casa.",
  ["Let's not talk about these old matters, {{sir|madam}}. Don't let them affect your appreciation of the scenery at the foot of the mountain."] = "Não vamos falar sobre esses assuntos antigos, {{senhor|senhora}}. Não deixe que eles afetem sua apreciação da paisagem no sopé da montanha.",
  ["Like {\"The Fool\",\"World\"}, this can match \"Fool and World\", but cannot match \"World and Fool\""] = "Assim como {\"The Fool\",\"World\"}, pode corresponder a \"Fool and World\", mas não pode corresponder a \"World and Fool\"",
  ["Lily: {{He|She}} saw it! {{He|She}} saw the red threads! {{He|She}} cannot be allowed to leave alive!"] = "Lily: {{Ele|Ela}} viu! {{Ele|Ela}} viu os fios vermelhos! {{Ele|Ela}} não pode sair vivo!",
  ["Lily: She saw it! She saw the red threads! She cannot be allowed to leave alive!"] = "Lily: Ela viu! Ela viu os fios vermelhos! Ela não pode sair viva!",
  ["LinearColorParams material parameter name cannot be empty"] = "O nome do parâmetro do material LinearColorParams não pode ficar vazio",
  ["List(Enum(All keys))"] = "Lista(Enum(Todas as chaves))",
  ["Little kid? {{Sir|Madam}}, that form of address is belittling to me."] = "Garotinho? {{Senhor|Senhora}}, essa forma de tratamento é depreciativa para mim.",
  ["Look, {{sir|madam}}, what a beautiful snowy mountain. Interested in an exhilarating cliffside race?"] = "Olha, {{senhor|senhora}}, que linda montanha nevada. Interessado em uma emocionante corrida no penhasco?",
  ["LuaDict(Enum(All Skill Slots), IdGroup(Skill))."] = "LuaDict(Enum(Todos os slots de habilidade), IdGroup(Habilidade)).",
  ["Start Lua GC object allocation profiling"] = "Iniciar perfil de alocação de objetos Lua GC",
