  ["QQ Zone"] = "Zona QQ",
  ["QTE skill (QTE performance, actually an extra skill button)."] = "Habilidade QTE (desempenho QTE, na verdade um botão de habilidade extra).",
  ["QTE End event listener"] = "Ouvinte de evento QTE End",
