  ["{\n \"Light Attack\": \"LightHit\", \n \"Knockback\": \"HitBack\", \n \"Knockdown\": \"HitDown\", \n \"Knockup\": \"HitFly\", \n \"Launch\": \"HitFloat\", \n \"Drag\": \"HitDrag\", \n \"Stiff Attack\": \"HitStiff\", \n \"Boxing light hit\": \"BoxHitLight\", \n \"Boxing heavy hit\": \"BoxHitHeavy\" \n}"] = "{\n \"Light Attack\": \"LightHit\", \n \"Knockback\": \"HitBack\", \n \"Knockdown\": \"HitDown\", \n \"Knockup\": \"HitFly\", \n \"Launch\": \"HitFloat\", \n \"Drag\": \"HitDrag\", \n \"Stiff Attack\": \"HitStiff\", \n \"Golpe leve de boxe\": \"BoxHitLight\", \n \"Golpe pesado de boxe\": \"BoxHitHeavy\" \n}",
  ["{\n \"Represents facing rotates with the holder\": \"FALSE\", \n \"Represents facing remains unchanged in the world coordinate system\": \"TRUE\" \n}"] = "{\n \"Representa rotações de face com o suporte\": \"FALSE\", \n \"Representa face permanece inalterada no sistema de coordenadas mundial\": \"TRUE\" \n}",
