  ["{ \n \"Bool\": \"0\", \n \"Int\": \"1\", \n \"Str\": \"2\", \n \"nil\": \"3\" \n } \n Expresses the parameter type corresponding to the parameter position on ParamValues"] = "{ \n \"Bool\": \"0\", \n \"Int\": \"1\", \n \"Str\": \"2\", \n \"nil\": \"3\" \n } \n Expressa o tipo de parâmetro correspondente à posição do parâmetro em ParamValues",
  ["{\n \"Puddle (similar to Tingen's puddle material, not actual water surface)\": \"0\", \n \"Grass\": \"1\", \n \"Stone\": \"2\", \n \"Dirt\": \"3\", \n \"Wood\": \"4\", \n \"Blanket\": \"5\", \n \"Fabric\": \"6\", \n \"Glass\": \"7\", \n \"Ice\": \"8\", \n \"Marsh\": \"9\", \n \"Solid Metal\": \"10\", \n \"Sand\": \"11\", \n \"Snow\": \"12\", \n \"Steel Plate\": \"13\", \n \"Tile Puddle\": \"14\", \n \"Water Surface\": \"15\", \n \"Wood Board\": \"16\" \n}"] = "{\n \"Poça (semelhante ao material da poça de Tingen, não à superfície real da água)\": \"0\", \n \"Grama\": \"1\", \n \"Pedra\": \"2\", \n \"Sujeira\": \"3\", \n \"Madeira\": \"4\", \n \"Cobertor\": \"5\", \n \"Tecido\": \"6\", \n \"Vidro\": \"7\", \n \"Gelo\": \"8\", \n \"Pântano\": \"9\", \n \"Metal Sólido\": \"10\", \n \"Areia\": \"11\", \n \"Neve\": \"12\", \n \"Placa de Aço\": \"13\", \n \"Poça de Azulejo\": \"14\", \n \"Superfície da Água\": \"15\", \n \"Tábua de Madeira\": \"16\" \n}",
  ["{ \n \"Triple jump landing\": 0, \n \"x key landing\": 1 \n }"] = "{ \n \"Aterrissagem com salto triplo\": 0, \n \"aterrissagem com tecla x\": 1 \n }",
  ["{\n \"Upper layer passed LockTarget\": \"0\", \n \"Holder\": \"1\", \n \"Originator\": \"2\", \n \"Primary aggro target\": \"3\" \n}"] = "{\n \"Camada superior passada no LockTarget\": \"0\", \n \"Holder\": \"1\", \n \"Originator\": \"2\", \n \"Alvo primário ameaça\": \"3\" \n}",
  ["{\n \"Not specified\": \"\", \n \"All enemy players\": \"Enemy(Player)\", \n \"All enemy players (including corpses)\": \"Enemy(Player)(IncludeDead)\" \n}"] = "{\n \"Não especificado\": \"\", \n \"Todos os jogadores inimigos\": \"Enemy(Player)\", \n \"Todos os jogadores inimigos (incluindo cadáveres)\": \"Enemy(Player)(IncludeDead)\" \n}",
  ["{\n \"Unspecified\": \"\", \n \"Hit target count (use this parameter after range hit in skills and spell fields)\": \"hitnum\", \n \"Filter target count (use this parameter when using target filtering)\": \"tarnum\", \n \"Class resource change value (including upward overflow value)\": \"propdiff\", \n \"Class resource change value (actual change value)\": \"proprealdiff\" \n}"] = "{\n \"Unspecified\": \"\", \n \"Contagem de alvos de acertos (use este parâmetro após alcance atingido em habilidades e campos de feitiços)\": \"hitnum\", \n \"Contagem de alvos de filtro (use este parâmetro ao usar a filtragem de alvos)\": \"tarnum\", \n \"Valor de mudança de recurso de classe (incluindo valor de estouro ascendente)\": \"propdiff\", \n \"Valor de mudança de recurso de classe (valor de mudança real)\": \"proprealdiff\" \n}",
  ["{\n \"Not specified type\": \"\", \n \"Neutral Buff\": \"0\", \n \"Buff\": \"1\", \n \"Debuff\": \"2\" \n}"] = "{\n \"Tipo não especificado\": \"\", \n \"Buff Neutro\": \"0\", \n \"Buff\": \"1\", \n \" Penalidade \": \"2\" \n}",
  ["{\n \"Calculate distance from capsule center\": \"False\", \n \"Calculate distance from capsule edge\": \"True\" \n}"] = "{\n \"Calcular distância do centro da cápsula\": \"Falso\", \n \"Calcular distância da borda da cápsula\": \"Verdadeiro\" \n}",
  ["{\n \"All (default value)\": \"All\", \n \"Enemy\": \"Enemy\", \n \"Friendly (excluding self)\": \"Friend\", \n \"Friendly\": \"FriendAndSelf\", \n}"] = "{\n \"Todos (valor padrão)\": \"Todos\", \n \"Inimigo\": \"Inimigo\", \n \"Amigável (excluindo eu mesmo)\": \"Amigo\", \n \"Amigável\": \"FriendAndSelf\", \n}",
  ["{\n \"All players\": \"0\", \n \"Skill/buff holder\": \"1\", \n \"Locked target\": \"2\" \n}"] = "{\n \"Todos os jogadores\": \"0\", \n \"Titular de habilidade/buff\": \"1\", \n \"Alvo bloqueado\": \"2\" \n}",
  ["{ \n \"Increase or decrease\": \"both\", \n \"Decrease\": \"down\", \n \"Increase\": \"up\" \n }"] = "{ \n \"Aumentar ou diminuir\": \"ambos\", \n \"Diminuir\": \"para baixo\", \n \"Aumentar\": \"para cima\" \n }",
  ["{\n \"Big Windmill (joystick direction, full-body animation)\": \"0\", \n \"Wheel rolling (facing direction, full-body animation)\": \"1\", \n \"Skateboard shoes (joystick direction, half-body animation)\": \"2\", \n \"Pacing and scratching head (facing direction, full-body animation)\": \"3\" \n}"] = "{\n \"Big Windmill (direção do joystick, animação de corpo inteiro)\": \"0\", \n \"Rolamento da roda (direção voltada, animação de corpo inteiro)\": \"1\", \n \"Sapatos de skate (direção do joystick, animação de meio corpo)\": \"2\", \n \"Andando e coçando a cabeça (direção voltada, animação de corpo inteiro)\": \"3\" \n}",
  ["{\n\"Monster\": \"1\",\n\"NPC\": \"2\",\n\"Scene Object\": \"3\"\n}"] = "{\n\"Monstro\": \"1\",\n\"NPC\": \"2\",\n\"Objeto de cena\": \"3\"\n}",
  ["{\n \"Skill/buff object target (holder/originator)\": \"0\", \n \"Level/scene as target\": \"1\", \n \"Objects in range as target\": \"2\", \n \"Target filter as target\": \"3\", \n \"Blackboard tarlist\": \"4\" \n}"] = "{\n \"Alvo do objeto de habilidade/buff (detentor/originador)\": \"0\", \n \"Nível/cena como alvo\": \"1\", \n \"Objetos no alcance como alvo\": \"2\", \n \"Filtro de alvo como alvo\": \"3\", \n \"Lista de tarifários do quadro-negro\": \"4\" \n}",
  ["{ \n \"Press or release\": \"both\", \n \"Press\": \"down\", \n \"Release\": \"up\" \n }"] = "{ \n \"Pressione ou solte\": \"ambos\", \n \"Pressione\": \"para baixo\", \n \"Libere\": \"para cima\" \n }",
  ["{\n\"None\": \"\", \n\"Slow\": \"SpeedDown\", \n\"Slumber\": \"Sleep\", \n\"Imprisonment\": \"Stuck\", \n\"Stun\": \"Dizzy\", \n\"Silence\": \"Silent\", \n\"Horror\": \"CharTerror\", \n\"Stiff\": \"Stiff\", \n\"Stagnation\": \"DodgeLimit\"\n}"] = "{\n\"None\": \"\", \n\"Slow\": \"SpeedDown\", \n\"Slumber\": \"Sleep\", \n\"Aprisionamento\": \"Stuck\", \n\"Stun\": \"Dizzy\", \n\"Silence\": \"Silent\", \n\"Horror\": \"CharTerror\", \n\"Rígido\": \"Rígido\", \n\"Estagnação\": \"DodgeLimit\"\n}",
  ["{\n \"None\": \"\", \n \"Invisibility\": \"Stealth\", \n \"Taunt\": \"Taunt\", \n \"Super Armor\": \"Endure\", \n \"Horror\": \"Terror\", \n \"Invisibility (Lock-on immunity only)\": \"CharacterStealth\", \n \"Petrification\": \"StoneState\", \n \"General Boss Mechanism\": \"NormalBossMechanism\" \n}"] = "{\n \"None\": \"\", \n \"Invisibility\": \"Stealth\", \n \" Provocar \": \" Provocar \", \n \"Super Armor\": \"Endure\", \n \"Horror\": \"Terror\", \n \"Invisibility (Lock-on Immunity Only)\": \"CharacterStealth\", \n \"Petrificação\": \"StoneState\", \n \"Mecanismo Geral Chefe\": \"NormalBossMechanism\" \n}",
  ["{\n \"No restriction\": \"0\", \n \"Restrict skill resurrection\": \"1\", \n \"Restrict self-function resurrection\": \"2\", \n \"Prohibit resurrection\": \"3\" \n}"] = "{\n \"Sem restrição\": \"0\", \n \"Restringir ressurreição de habilidade\": \"1\", \n \"Restringir ressurreição de autofunção\": \"2\", \n \"Proibir ressurreição\": \"3\" \n}",
  ["{\n \"According to item table\": \"1\", \n \"Bound\": \"2\", \n \"Non-bound\": \"3\" \n}"] = "{\n \"De acordo com a tabela de itens\": \"1\", \n \"Bound\": \"2\", \n \"Não vinculado\": \"3\" \n}",
  ["{\n\"Listen for destruction (default)\": \"false\", \n\"Listen for Death Skill\": \"true\"\n}"] = "{\n\"Ouvir a destruição (padrão)\": \"false\", \n\"Ouvir a habilidade da morte\": \"true\"\n}",
  ["{\n\"Restrict to Walking Speed\": \"1\",\n\"Restrict to Running Speed\": \"2\"\n}"] = "{\n\"Restringir à velocidade de caminhada\": \"1\",\n\"Restringir à velocidade de corrida\": \"2\"\n}",
  ["{\n \"Interrupt with state end\": \"0\", \n \"Interrupt with skill end\": \"1\", \n \"Do not interrupt\": \"2\" \n}"] = "{\n \"Interrupção com fim do estado\": \"0\", \n \"Interrupção com fim da habilidade\": \"1\", \n \"Não interromper\": \"2\" \n}",
  ["{\n \"Automatically cancel highlight after click\": \"0\", \n \"Do not automatically cancel highlight after click\": \"1\", \n}"] = "{\n \"Cancelar automaticamente o destaque após clicar\": \"0\", \n \"Não cancelar automaticamente o destaque após clicar\": \"1\", \n}",
  ["{ {skillTag1, 1.0}, {skillTag2, 2.0}} means increasing the speed of skillTag1 skills by 1x and skillTag2 skills by 2x."] = "{ {skillTag1, 1.0}, {skillTag2, 2.0}} significa aumentar a velocidade das habilidades skillTag1 em 1x e das habilidades skillTag2 em 2x.",
  ["{ {skillType1, 1.0}, {skillType2, 2.0}} means increasing the speed of skillType1 skills by 1x and skillType2 skills by 2x."] = "{{skillType1, 1.0}, {skillType2, 2.0}} significa aumentar a velocidade das habilidades skillType1 em 1x e das habilidades skillType2 em 2x.",
  ["{ {skillid1, 1.0}, {skillid2, 2.0}} means increasing the rate of skillid1 by 1 time, and skillid2 by 2 times."] = "{{skillid1, 1.0}, {skillid2, 2.0}} significa aumentar a taxa de skillid1 em 1 vez e de skillid2 em 2 vezes.",
  ["{\"Quantity of %ist Spell Field\"}"] = "{\"Quantidade do %ist campo de feitiço\"}",
  ["{\"Number of No. %i Traps\"}"] = "{\"Número de %i armadilhas\"}",
