  ["{\"id\":1000,\"title\":\"Download Paused\",\"body\":\"Your network environment has switched to mobile data, so the game download has been paused. We will automatically resume the download when you are on a WiFi connection.\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Download pausado\",\"body\":\"Seu ambiente de rede mudou para dados móveis, então o download do jogo foi pausado. Retomaremos automaticamente o download quando você estiver em uma conexão WiFi.\",\"pushMode\":0,\"delayInSeconds\":1}",
  ["{\"id\":1000,\"title\":\"Downloading Resources\",\"body\":\"Downloading in the background for you\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Baixando recursos\",\"body\":\"Baixando em segundo plano para você\",\"pushMode\":0,\"delayInSeconds\":1}",
  ["{\"id\":1000,\"title\":\"Resource download failed\",\"body\":\"Download failed\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Falha no download do recurso\",\"body\":\"Falha no download\",\"pushMode\":0,\"delayInSeconds\":1}",
  ["{\"id\":1000,\"title\":\"Resource Download Complete\",\"body\":\"Download Complete\",\"pushMode\":0,\"delayInSeconds\":1}"] = "{\"id\":1000,\"title\":\"Download de recursos concluído\",\"body\":\"Download concluído\",\"pushMode\":0,\"delayInSeconds\":1}",
  ["{\"notificationTitle\": \"Download Paused\",\"notificationContent\":\"Your network environment has switched to mobile data, so the game download has been paused. We will automatically resume the download when you are on a WiFi connection.\",\"showProgress\":false}"] = "{\"notificationTitle\": \"Download Pausado\",\"notificationContent\":\"Seu ambiente de rede mudou para dados móveis, então o download do jogo foi pausado. Retomaremos automaticamente o download quando você estiver em uma conexão WiFi.\",\"showProgress\":false}",
  ["{ \"notificationTitle\": \"Resource download failed\", \"notificationContent\": \"Download failed\", \"showProgress\": false }"] = "{ \"notificationTitle\": \"Falha no download do recurso\", \"notificationContent\": \"Falha no download\", \"showProgress\": false }",
  ["{\"notificationTitle\":\"Downloading Resources\",\"notificationContent\":\"{2}%\",\"showProgress\":true,\"progress\":{2}}"] = "{\"notificationTitle\":\"Baixando recursos\",\"notificationContent\":\" {2} %\",\"showProgress\":true,\"progress\": {2} }",
  ["{\"notificationTitle\":\"Resource download complete\",\"notificationContent\":\"Download complete\",\"showProgress\":false}"] = "{\"notificationTitle\":\"Download do recurso concluído\",\"notificationContent\":\"Download completo\",\"showProgress\":false}",
