  ["{\"The %ith Displacement destination\"}"] = "{\"O %ésimo destino do deslocamento\"}",
  ["{\"Extra Pitch angle of the %ist bullet\"}"] = "{\"Ângulo de inclinação extra do %ist bullet\"}",
  ["{\"Extra Yaw angle for the %ist bullet\"}"] = "{\"Ângulo de guinada extra para o marcador %ist\"}",
