  ["One-Stroke Component Passable Grid"] = "Grade transitável de componente de um curso",
  ["One-Stroke Component End"] = "Fim do componente de um curso",
  ["One-Stroke Component Start"] = "Início do componente de um curso",
  ["One-Stroke Component Locked Treasure Chest"] = "Baú de tesouro bloqueado com componente de um golpe",
  ["One-Stroke End Point Initial State"] = "Estado inicial do ponto final de um curso",
  ["One-Stroke End Point Activated State"] = "Estado ativado do ponto final de um curso",
  ["One-Stroke End Point Locked State"] = "Estado bloqueado do ponto final de um curso",
